#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    if (n % 2 == 0) {
        cout << "Marsel\n";
        return 0;
    }

    bool hasDivisor = false;

    for (long long i = 2; i * i <= m; ++i) {
        if (m % i == 0 && (i >= k || m / i >= k)) {
            hasDivisor = true;
            break;
        }
    }

    if (k == 1 && m > 1) {
        hasDivisor = true;
    }

    cout << (hasDivisor ? "Timur\n" : "Marsel\n");
    return 0;
}

#include <bits/stdc++.h>
#define ll long long int
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    string one = "Timur", two = "Marsel";

    if (n % 2 == 0) {
        cout << two << '\n';
        return 0;
    }

    bool div = false;

    for (ll i = 2; i * i <= m; ++i) {
        if (m % i != 0) continue;

        int div1 = static_cast<int>(i);
        int div2 = m / div1;

        if (div1 >= k || div2 >= k) {
            div = true;
            break;
        }
    }

    if (k == 1 && m > 1) div = true;

    cout << (div ? one : two) << '\n';
    return 0;
}

